mapper.select:
select m.PORTFOLIO_ID portfolioId, m.PORTFOLIO_TYPE portfolioType, m.PORTFOLIO_NAME portfolioName, m.VDATE, m.MDATE, m.PROFIT_TYPE profitType, y.IS_GUARANTEE isGuarantee, y.OPEN_TYPE openType, y.RAISE_TYPE raiseType, y.INVEST_NATURE investNature, n.CALENDAR_ID calendarId, x.OPEN_MODE openMode, m.RISK_ENABLED riskEnabled from PTL_PORTFOLIO m inner join PA_PTL_PORTFOLIO y on m.PORTFOLIO_ID=y.PORTFOLIO_ID left join REP_PROD_INFO x on m.PORTFOLIO_ID=x.PROD_ID left join FIN_PRODUCT n on m.PORTFOLIO_ID=n.FINPROD_ID
m.PORTFOLIO_ID in
#{item}

SELECT PARA_CODE,RKEY,RVALUE FROM (
    SELECT 
       PARA_CODE || ':' || PARA_GRANULARITY PARA_CODE,
       NVL(PORTFOLIO_ID,'') || decode(NVL(PORTFOLIO_ID,''),'','',decode(NVL(ASSET_CODE,''),'','',',')) || NVL(ASSET_CODE,'') RKEY,
       sum(CHANGE_VALUE) RVALUE 
    FROM RSK_INDICATOR_PARA_CALCDETAIL
    WHERE SUP_DATE = #{valDate, jdbcType=DATE}
    GROUP BY PARA_CODE,PARA_GRANULARITY,PORTFOLIO_ID,ASSET_CODE
)

    PARA_CODE = #{paraCode, jdbcType=VARCHAR}

    AND RKEY in

        #{item}

select m.PARA_CODE,y.PARA_NAME paraName,'FIX' as PARA_GRANULARITY,'FIX' AS PARA_DISPLAY_TYPE,m.CONTENT,null as redisField ,'N' as isFreshCanTrd,'N' as isUpRedis,'String' as paramDataType,null as paramMathType, y.IS_FORBID isForbid from RSK_ISUP_FIX_RECODE m inner join (select MAX(RSK_ISUP_FIX_RECODE.VALID_DATE) as VALID_DATE,PARA_CODE from RSK_ISUP_FIX_RECODE where RSK_ISUP_FIX_RECODE.VALID_DATE<=to_date('${valDate}','yyyy-MM-dd') group by PARA_CODE) n on m.PARA_CODE=n.PARA_CODE and m.VALID_DATE=n.VALID_DATE inner join RSK_ISUP_INDICATOR_PARA y on m.PARA_CODE=y.PARA_CODE
m.PARA_CODE in
#{item}

select UNITE_ID uniteId, PRT_BAG_ID prtBagId, IND_ID indId from RSK_INDIVID_UNITE
UNITE_ID in (select UNITE_ID from RSK_INDIVID_UNITE a where a.IND_ID in
#{item}
)

select UNITE_ID uniteId, PRT_BAG_ID prtBagId, IND_ID indId, START_DATE startDate, END_DATE endDate, UNITE_TYPE uniteType, FINPROD_ID finprodId, WARN_COND warnCond, APPROVE_COND approveCond, FOUL_COND foulCond from RSK_INDIVID_SPECIAL_STAGE
UNITE_TYPE=#{uniteType}
and IND_ID in
#{item}

select DEL_ID delId, PRT_BAG_ID prtBagId, IND_ID indId, START_DATE startDate, END_DATE endDate, FINPROD_ID finprodId from RSK_INDIVID_ASSET_DEL
IND_ID in
#{item}

select DISTINCT PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL


    PTL_BAG_ID in

        #{item}

select
COMMON_BUSINESS_TYPE commonBusinessType,
PARA_CODE paraCode,
REDIS_MODEL redisModel
from RSK_BUSINESS_REDIS_CONFIG


        and COMMON_BUSINESS_TYPE in ${commonBusinessType}


        and PARA_CODE = #{paraCode}


        and REDIS_MODEL = #{paraCode}
